cat > /tmp/test_amounts.js << 'EOF'
import { createInvoice, issueInvoice, applyVoucher } from '/private/tmp/100-tricks-runs/d40/with/m5/src/invoices.js';
import { balanceDue } from '/private/tmp/100-tricks-runs/d40/with/m5/src/payments.js';

// Test 1: Voucher case
const inv1 = createInvoice({
  customerId: 'C-001',
  issueDate: '2026-09-01',
  lines: [{ sku: 'DES-HOUR', qty: 5 }],
}).value;

const withVoucher = applyVoucher(inv1, { code: 'PROMO', amount: 5000 }).value;
const issued1 = issueInvoice(withVoucher, []).value;
console.log('Voucher case - amountDue:', balanceDue(issued1));

// Test 2: Different amount (LOGO-PACK)
const inv2 = createInvoice({
  customerId: 'C-002',
  issueDate: '2026-09-01',
  lines: [{ sku: 'LOGO-PACK', qty: 1 }],
}).value;

const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;
console.log('LOGO-PACK case - amountDue:', balanceDue(issued2));

// Test 3: Multiple days with various amount
const inv3 = createInvoice({
  customerId: 'C-001',
  issueDate: '2026-09-01',
  lines: [{ sku: 'DES-HOUR', qty: 5 }],
}).value;

const issued3 = issueInvoice(inv3, ['INV-2026-0001', 'INV-2026-0002']).value;
console.log('Standard case - amountDue:', balanceDue(issued3));
console.log('Fee for 30 days:', balanceDue(issued3) * 0.0004 * 30);
EOF
node /tmp/test_amounts.js
